import sys,collections,heapq,itertools,functools,bisect
def solve(data):
    h,w,sx,sy,tx,ty=map(int,data.split());sx-=1;sy-=1;tx-=1;ty-=1;d=[[-1]*w for _ in range(h)];d[sx][sy]=0;q=collections.deque([(sx,sy)])
    while q:
        x,y=q.popleft()
        for dx,dy in [(1,2),(1,-2),(-1,2),(-1,-2),(2,1),(2,-1),(-2,1),(-2,-1)]:
            u,v=x+dx,y+dy
            if 0<=u<h and 0<=v<w and d[u][v]<0:d[u][v]=d[x][y]+1;q.append((u,v))
    return d[tx][ty]

if __name__=="__main__":
    a=solve(sys.stdin.buffer.read().decode())
    print(" ".join(map(str,a)) if isinstance(a,(list,tuple)) else a)
